style.css:
@-moz-document domain("roblox.com") {
/* Change the background color of the entire page */
    body {
        background-color: #1a1a1a;
        color: white;
        font-family: 'Arial', sans-serif;
    }

    /* Style the header */
    .navbar {
        background-color: #232323;
        border-bottom: 1px solid #444;
    }

    /* Style the logo in the header */
    .roblox-header-logo {
        filter: brightness(0) invert(1);
    }

    /* Change the link color */
    a {
        color: #00aaff;
    }

    /* Style the buttons */
    .btn {
        background-color: #1c1c1c;
        border: 2px solid #00aaff;
        color: #00aaff;
    }

    .btn:hover {
        background-color: #00aaff;
        color: #fff;
    }

    /* Change background color of the navigation bar */
    .nav-tabs {
        background-color: #232323;
    }

    /* Style the footer */
    .footer {
        background-color: #1a1a1a;
        color: white;
        border-top: 1px solid #444;
    }

    /* Customizing the content section */
    .content {
        background-color: #121212;
        padding: 20px;
    }

    /* Add a shadow effect to the cards */
    .card {
        background-color: #333;
        border-radius: 10px;
        box-shadow: 0 4px 6px rgba(0, 0, 0, 0.3);
    }

    .card:hover {
        box-shadow: 0 6px 10px rgba(0, 0, 0, 0.5);
    }

    /* Change the color of the search bar */
    .search-bar input {
        background-color: #222;
        color: white;
        border: 1px solid #444;
    }

    /* Adjust the profile page layout */
    .profile-header {
        background-color: #1a1a1a;
        color: #fff;
    }

    .profile-card {
        background-color: #222;
        color: #fff;
        border: 1px solid #444;
    }
}
